insert into public.hr_challenge_enriched (code,doc,embedding) values
  ('PF1','Do I need a written employment contract?. Contracts & engagement. The Fair Work Act does not mandate a written contract for most ongoing employees, but one is effectively required to properly engage casuals, fixed-term staff, and anyone on an Individual Flexibility Arrangement. Whatever is agreed, it cannot undercut the NES or the applicable modern award — any such term is void and the statutory minimum applies instead. Common questions: Do I need to give him something in writing or is a handshake fine? Can I just use the contract I found on Google? What actually has to be in an employment letter? Is my old contract template still legal?','[-0.055529,0.042999,0.038206,-0.058227,-0.091574,0.120775,0.003254,0.016808,-0.044441,0.012864,-0.041641,0.051723,-0.084000,0.036346,0.020294,0.029489,0.007578,0.038137,0.033379,-0.025193,0.021907,0.069737,-0.021140,-0.072222,-0.050389,-0.055011,0.087756,0.076824,0.006460,0.057222,-0.005073,0.015363,0.096880,-0.034488,0.034407,-0.011575,0.038670,-0.042692,-0.068902,-0.048038,0.010671,-0.033956,-0.007899,0.095155,0.039631,-0.022627,0.014305,-0.021675,-0.066887,0.063912,0.011266,-0.036918,0.058799,0.024098,-0.016184,-0.027983,-0.023732,-0.038593,-0.033154,-0.024009,-0.009695,-0.008632,-0.054068,0.030803,-0.017704,-0.053053,-0.010840,0.017703,-0.038884,-0.035246,-0.056989,-0.033842,0.024546,-0.047430,-0.001287,-0.034189,-0.039339,0.005602,0.058170,-0.113444,-0.031297,-0.006234,0.016272,0.037970,-0.010675,-0.019458,0.045955,-0.039330,0.063200,0.054477,0.042412,-0.010188,0.026448,-0.114869,-0.067983,0.028068,0.075438,0.035708,-0.078450,0.024723,-0.036562,-0.019274,-0.012187,0.035522,0.064526,0.029747,-0.029938,-0.075709,0.012695,0.042220,-0.031603,0.004008,-0.046668,-0.011585,0.036428,-0.033768,-0.102857,-0.013706,-0.000380,-0.036070,-0.026802,0.051952,-0.115133,0.079830,-0.127847,-0.041140,0.040890,0.000000,0.088618,0.124350,-0.057350,0.101306,0.043855,0.000679,0.022973,0.016322,-0.043539,0.096964,0.001734,0.108874,0.062028,